def replace_range(doc,start,end,writer):
    nodes=list(doc.element.body); begin=next((i for i,n in enumerate(nodes) if n.tag.endswith('}p') and Paragraph(n,doc).text==start),None)
    if begin is None: return
    finish=next(i for i in range(begin+1,len(nodes)) if nodes[i].tag.endswith('}p') and Paragraph(nodes[i],doc).text==end)
    anchor=nodes[finish]
    for n in nodes[begin:finish]: n.getparent().remove(n)
    old=set(doc.element.body)
    writer(doc)
    for n in list(doc.element.body):
        if n not in old and not n.tag.endswith('}sectPr'): anchor.addprevious(n)

def apply_budget(doc,is_plan):
    start='4 Базовый план по стоимости' if is_plan else '5 Предварительный бюджет'
    end='5 Управление содержанием и требованиями' if is_plan else '6 Высокоуровневые риски и приемка'
    def main(d):
        section(d,start)
        text(d,'Редакция бюджета 2.0 от 07.11.2026 заменяет прежний расчет 8,4 млн ₽. Окно коммерческого развития август–декабрь сохранено; цены проверены на новую дату. Учебная поставка и ее фактические затраты этим расчетом не переоцениваются.')
        labour(d); costs(d)
        text(d,f'Цена договора для заказчика с НДС — {rub(GROSS)}; расчет налогов, прибыли и месячного PV приведен в приложении А. Конечная цена и новая база подлежат решению спонсора.')
    replace_range(doc,start,end,main)
    replace_range(doc,'Приложение А Основания расчётной модели','Материалы и навигация',lambda d:(section(d,'Приложение А Пересмотр бюджета и коммерческая цена'),commercial(d)))
    # Replace obsolete business case while retaining scope and assigned roles.
    if not is_plan:
        replace_range(doc,'2 Бизнес потребность и экономическое обоснование','3 Границы и высокоуровневые требования',lambda d:(section(d,'2 Бизнес потребность и экономическое обоснование'),text(d,f'Развитие объединяет учет производства, запасов и продаж. Цель — снижение потерь, экономия труда и дополнительная маржа. Валовой эффект 450 000 ₽ в месяц является гипотезой. После эксплуатации 56 358 ₽ расчетный эффект до налогов хозяйства — {rub(EFFECT)}. При цене внедрения {rub(GROSS)} с НДС простая окупаемость — {float(GROSS/D(EFFECT)):.1f} месяца получения эффекта. Проверка денежных потоков и чувствительности приведена в приложении А. Это коммерческое расширение, а не подтвержденные результаты учебной базы.')))
    for p in list(doc.paragraphs)+[p for t in doc.tables for row in t.rows for c in row.cells for p in c.paragraphs]:
        s=p.text
        if 'Расчётный лимит 8,4 млн' in s: p.text=f'Пересмотренная себестоимость {rub(COST)}; цена с НДС {rub(GROSS)}. Источники и допущения — приложение А.'
        elif s.startswith('Основные допущения модели:'): p.text='Финансовые допущения заменены редакцией бюджета 2.0 от 07.11.2026: четыре сотрудника, пять месяцев, один совмещенный технический исполнитель; общая система налогообложения. Расчет в разделе стоимости и приложении А. Функциональные границы развития и ответственность сохраняются.'
        elif 'общий лимит 8,4 млн' in s: p.text=s.replace('общий лимит 8,4 млн ₽',f'новая себестоимость {rub(COST)}')
        elif 'лимит 8,4 млн ₽' in s: p.text=s.replace('лимит 8,4 млн ₽',f'пересмотренная цена с НДС {rub(GROSS)} (подлежит согласованию)')
        elif s.startswith('Учебный расчет контроля'): p.text='Контроль EVM после утверждения новой базы использует BAC '+rub(BAC)+'. CPI = EV/AC, SPI = EV/PV. Старый числовой пример с BAC 8 млн исключен; фактические показатели проекта отсутствуют.'
        elif 'лимит 320 тыс.' in s: p.text=s.replace('лимит 320 тыс. ₽',f'лимит {rub(LICENSES)} с основной поставкой')
        elif 'Фиксированная аренда 20 тыс.' in s: p.text='Два VPS-32-RU по 12 179 ₽ в месяц; хранение внешних копий — плановый лимит 2 000 ₽/месяц; суммарно 26 358 ₽. Ресурсы и источник — раздел стоимости.'
    doc.core_properties.version='2.0'
    # Regenerate linked contents because replacing finance chapters removes bookmarks.
    nodes=list(doc.element.body)
    first=next(n for n in nodes if n.tag.endswith('}p') and Paragraph(n,doc).text=='Содержание')
    anchor=next(n for n in nodes if n.tag.endswith('}p') and Paragraph(n,doc).text=='Актуальный объём проекта')
    for n in nodes[nodes.index(first):nodes.index(anchor)]: n.getparent().remove(n)
    for p in doc.paragraphs:
        for tag in ['bookmarkStart','bookmarkEnd']:
            for n in list(p._p.findall('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'+tag)):
                n.getparent().remove(n)
    from build_project_management import add_contents
    add_contents(doc,anchor)

def main():
    QA.mkdir(parents=True,exist_ok=True)
    for name in ['Устав_проекта.docx','План_управления_проектом.docx']:
        path=FOLDER/name
        original=QA/(path.stem+'_before.docx')
        if not original.exists(): original.write_bytes(path.read_bytes())
        doc=Document(original); apply_budget(doc,name.startswith('План'))
        doc.save(path); print(path)
    (FOLDER/'Расчет_бюджета_2026.json').write_text(json.dumps({'date':'2026-11-07','FOT':FOT,'labour_with_taxes':LABOUR,'licenses':LICENSES,'computers_monitors':PCS,'cloud':CLOUD,'overhead':OVERHEAD,'direct':DIRECT,'BAC':BAC,'cost_with_reserves':COST,'price_net':str(PRICE),'VAT':str(VAT),'price_gross':str(GROSS),'profit_tax':str(TAX),'net_profit':str(NET),'monthly_PV':PV},ensure_ascii=False,indent=2),encoding='utf-8')
    md=['# Пересмотр бюджета от 07.11.2026',f'Себестоимость с резервами: {rub(COST)}. BAC: {rub(BAC)}. Цена с НДС: {rub(GROSS)}.',f'Цель: маржа 20% до налога, 15% после налога; чистая прибыль {rub(NET)}.','Час = gross / 168; день = gross / 21. С взносами: ×1,302. Оклады: PM 220 000, архитектор-разработчик 300 000, аналитик 210 000, QA 180 000.', 'Все четыре участника по 1 FTE. Льготные налоговые режимы не предполагаются. Учебная поставка отдельно от коммерческой модели.','## Источники']
    md.extend(f'- [{c} {n}]({u}): {note}' for c,n,u,note in SOURCES)
    md.append('## Примеры зарплат и цен\n\nПроверено 07.11.2026. Gross — до НДФЛ. Прямые HH-ссылки ведут на объявления СПб и/или удаленной работы. Страницы могут архивироваться. Данные сверены по выдаче, прямые карточки частично ограничены для автоматического просмотра.\n\n| Статья | Пример | Источник |\n|---|---|---|\n'+'\n'.join(f'| {n} | {note} | [Открыть]({url}) |' for n,note,url in EXAMPLES))
    md.append('## НДФЛ\n\n13% до 2,4 млн ₽ годовой базы; 15% только на превышение до 5 млн. Порог 200 тыс. в месяц сам по себе не переключает ставку. При 300 тыс. × 12 налог 492 тыс.; при найме только на август–декабрь: 1,5 млн × 13% = 195 тыс. При работе с января налог за август–декабрь 219 тыс. В бюджете принят найм с августа без прежних выплат. При прежних выплатах проверяются также предельная база взносов и вычеты. Источник S09.')
    md.append('## Что является оценкой\n900 000 ₽ подрядчик, 2 000 ₽/месяц внешние копии, 60 000 ₽ обучение, 5% накладные, резервы 705 000 и 400 000, маржа 20%. Эти величины требуют КП или решения; не названы установленной рыночной ценой. ПК и монитор — наличная цена, безналичную уточнить. НДФЛ рассчитан без других доходов, 0,2% травматизма требует подтверждения СФР. Входной НДС не вычтен без счетов-фактур. Существующие 12 пользовательских ПК не покупаются повторно.')
    (FOLDER/'Обоснование_бюджета.md').write_text('\n\n'.join(md),encoding='utf-8')

if __name__=='__main__': main()
